#include <bits/stdc++.h>using namespace std; int main() {    int t;    cin >> t;    while (t--) {        int n;        cin >> n;        vector<int> a(n);        for (int i = 0; i < n; i++) {            cin >> a[i];        }        sort(a.begin(), a.end());        vector<int> x;        if (n > 0) {            x.push_back(a[0]);            for (int i = 1; i < n; i++) {                if (a[i] != a[i - 1]) {                    x.push_back(a[i]);                }            }        }        int m = 0;        int s = 0;        for (int i = 0; i < x.size(); i++) {            if (i > 0 && x[i] == x[i - 1] + 1) {                s++;            } else {                s = 1;             }                        if (s > m) {                m = s;            }        }        if (x.empty()) {            cout << 0 << endl;        } else {            cout << m << endl;        }    }}